-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "zhTW" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.hunter.ranged.Name"] = "遠程"
L["rm.era.hunter.ranged.Description"] = "所有獵人，1 至 60 級，所有天賦樹。以獵人印記、瞄準射擊與自動射擊拉怪。單人時由寵物坦怪：先上你自己的毒蛇釘刺，接著只有在法力高於一半時才使用瞄準射擊、秘法射擊與多重射擊，還沒有寵物時以震盪射擊放風箏。隊伍中，在自動射擊後立即使用瞄準射擊與多重射擊，讓自動射擊永遠不被延遲，團隊以外使用毒蛇釘刺，秘法射擊只在學會瞄準射擊之前或對即將死亡的目標使用。敵人太近時使用近戰技能，移動時使用瞬發技能，三個以上敵人時使用多重射擊與亂射。提醒：雄鷹守護（學會前為靈猴守護）、強擊光環、寵物照料、對精英與在副本中使用急速射擊、狂野怒火與種族技能、脅迫與假死。陷阱、摔絆、餵養寵物、寧神射擊與站位由你自行處理。"
L["rm.era.hunter.ranged.icyveins.Name"] = "遠程，延遲自動射擊（Icy Veins）"
L["rm.era.hunter.ranged.icyveins.Description"] = "預設關閉；如果你的遠程武器速度快於 3.0 秒，請啟用它。與「獵人：遠程」相同，但在隊伍中瞄準射擊與多重射擊一就緒就施放，即使會延遲自動射擊也一樣，從不使用毒蛇釘刺，並且每次拉怪都使用急速射擊、狂野怒火與種族技能。"
L["rm.era.hunter.ranged.simulator.Name"] = "遠程，團隊毒蛇釘刺（模擬器）"
L["rm.era.hunter.ranged.simulator.Description"] = "預設關閉；如果團隊有空間容納你的釘刺減益效果，請啟用它。與「獵人：遠程」相同，但在隊伍中隨時維持毒蛇釘刺（包括團隊中），在瞄準射擊與多重射擊都在冷卻時，若剩不到 5 秒就刷新，並且從不使用秘法射擊。"
L["rm.forever.hunter.ranged.Name"] = "遠程（Wowhead）"
L["rm.forever.hunter.ranged.Description"] = "適用於 1 至 60 級的所有遠程獵人（野獸控制、射擊，以及學會陸行鳥腳踢之前的生存），也是永久獵人的預設循環。拉怪：獵人印記、急速殺戮持續期間使用狙擊射擊、自動射擊。接著是你自己的毒蛇釘刺，在共用冷卻中兩次召喚獵鷹與一次秘法射擊（學會召喚獵鷹之前秘法射擊冷卻結束即使用），急速殺戮期間或對精英使用狙擊射擊、瞄準射擊。兩個以上敵人與你交戰時：以多重射擊取代瞄準射擊，附近有三個敵人時使用爆炸陷阱，五個時使用亂射。移動時：只使用瞬發射擊。近戰範圍內的怪物會吃到猛禽一擊與貓鼬撕咬。提醒：雄鷹守護（學會前為靈猴守護）、強擊光環、召喚與復活寵物、急速射擊、對精英或在地城中使用狂野怒火與血性狂暴、怪物貼身時使用脅迫。寵物指令、餵食、放風箏與假死由你自行處理；如果你使用孤狼，請停用寵物提醒。它從不讀取你的法力或任何人的生命力（永久版本會對插件隱藏這些資料），因此獵人印記與毒蛇釘刺會施放在每個目標上，治療寵物由你自行處理。"
L["rm.forever.hunter.ranged.mobalytics.Name"] = "遠程，節省法力（Mobalytics）"
L["rm.forever.hunter.ranged.mobalytics.Description"] = "Mobalytics 的節省法力升級打法，作為推薦的 Wowhead 遠程內建循環的替代，預設為停用：啟用它並停用那個，或提高它的優先順序。維持你自己的毒蛇釘刺，維持一隻召喚出的獵鷹，瞄準射擊（兩個以上敵人時用多重射擊），學會召喚獵鷹後不再使用秘法射擊；由於永久版本會隱藏目標生命力，因此不會對血量充足的目標召喚第二隻獵鷹。拉怪、近戰、移動與提醒都與 Wowhead 內建循環相同。"
L["rm.forever.hunter.survival.Name"] = "生存近戰（Wowhead）"
L["rm.forever.hunter.survival.Description"] = "當生存是你的主要天賦樹且已投入 21 點（陸行鳥腳踢所在層）後的雙持近戰生存（在此之前依指南建議由遠程內建循環帶你升級）。以獵人印記與毒蛇釘刺拉怪，接著是貓鼬撕咬、陸行鳥腳踢、猛禽一擊與反擊，三個以上敵人時使用爆炸陷阱。不在近戰範圍時進行射擊：毒蛇釘刺、秘法射擊、瞄準射擊、自動射擊。提醒：野獸守護、獵人印記（暴露獵物需要它）、對精英或在地城中使用急速射擊與血性狂暴、你持有目標注意力時使用威懾、寵物照料（永久版本中生命力是隱藏的，因此治療寵物由你自行處理）。選擇性的獻祭陷阱步驟預設關閉。"
L["rm.forever.hunter.survival.weave.Name"] = "生存雙手穿插（Wowhead）"
L["rm.forever.hunter.survival.weave.Description"] = "Wowhead 針對雙手武器生存獵人的進出穿插打法，作為推薦的生存近戰內建循環的替代，預設為停用：啟用它並停用那個，或提高它的優先順序。近戰時：貓鼬撕咬與猛禽一擊；當猛禽一擊還需 2.5 秒以上才就緒時，使用陸行鳥腳踢並退出近戰。不在近戰時：毒蛇釘刺、秘法射擊、瞄準射擊與自動射擊，直到猛禽一擊即將就緒，然後回到近戰。移動由你負責；RM 會依你的距離調整。"
L["rm.mop.hunter.beastmastery.Name"] = "推薦"
L["rm.mop.hunter.beastmastery.Description"] = "在野獸控制專精下自動選用。以獵人印記與擊殺命令開場，接著：擊殺射擊，擊殺命令（狂野怒火即將就緒時稍候片刻），黑鴉獵殺，山貓衝刺，有點天賦時使用凶暴野獸與你的第六層天賦射擊，五層狂亂（或四層即將消失）時使用專注射擊，但狂野怒火期間不用，對會存活較久的目標使用毒蛇釘刺，以眼鏡蛇射擊刷新它，集中值 80 或狂野怒火期間使用秘法射擊，然後是眼鏡蛇射擊（81 級前為穩固射擊）。兩個以上敵人與你交戰時，以多重射擊維持獸劈斬，面對大型怪群時只在集中值有餘時使用擊殺命令，三個起建議爆炸陷阱。提醒：寵物已召喚、復活並治療，雄鷹守護或鋼鷹守護，駁火反擊，熱情，以及值得時（精英、地城或團隊副本，或會存活較久的目標）使用狂野怒火、急速射擊、奔竄與種族技能。陷阱擺放、誤導、假死與防禦技能由你自行處理；心曠神怡與威懾的提醒預設關閉。"
L["rm.mop.hunter.marksmanship.Name"] = "推薦"
L["rm.mop.hunter.marksmanship.Description"] = "在射擊專精下自動選用。預先施放瞄準射擊，接著：成對施放穩固射擊以維持穩固集中（63 級起），奇美拉射擊，對會存活較久的目標使用毒蛇釘刺，射擊!使瞄準射擊變為瞬發時就使用，擊殺射擊，你的天賦，以及在目標生命力高於 80%、急速射擊或嗜血術期間、集中值 85 時，或奇美拉射擊再幾秒就就緒時讀條施放瞄準射擊。秘法射擊只在移動時使用；否則使用穩固射擊。四個以上敵人時：奇美拉射擊、瞬發瞄準射擊、多重射擊、擊殺射擊、爆炸陷阱。提醒與其他獵人內建循環相同。如果你偏好把多餘的集中值花在秘法射擊上，請使用秘法射擊版本。"
L["rm.mop.hunter.marksmanship.icyveins.Name"] = "秘法射擊消耗（Icy Veins）"
L["rm.mop.hunter.marksmanship.icyveins.Description"] = "射擊內建循環的替代方案，依照 Icy Veins、Method、wowtbc.gg 與 Hekili 的打法：只有在目標生命力高於 80% 或急速射擊、嗜血術期間才讀條施放瞄準射擊，多餘的集中值則改在 60 時用於秘法射擊。穩固集中在剩不到 4 秒時刷新；四個以上敵人時優先使用多重射擊。預設關閉：啟用它並停用射擊內建循環，或提高它的優先順序。"
L["rm.mop.hunter.survival.Name"] = "推薦"
L["rm.mop.hunter.survival.Description"] = "在生存專精下自動選用。以獵人印記、黑蝕箭與爆裂射擊開場，接著：爆裂射擊冷卻結束時及每次蓄勢待發時使用，擊殺射擊，對會存活較久的目標使用黑蝕箭，你的天賦，以眼鏡蛇射擊維持毒蛇釘刺，集中值 75、有獵殺快感時，或黑蝕箭不會很快就緒時在 55 使用秘法射擊，然後是眼鏡蛇射擊（81 級前為穩固射擊）。兩個以上敵人時：蓄勢待發且集中值全滿時優先使用多重射擊，爆裂射擊最多對五個目標，擊殺射擊，黑蝕箭，三個起使用爆炸陷阱，以多重射擊消耗集中值。提醒與其他獵人內建循環相同；為觸發蓄勢待發而放置陷阱由你自行處理。"
L["rm.mop.hunter.unspecialized.Name"] = "選擇專精前"
L["rm.mop.hunter.unspecialized.Description"] = "適用於 1 至 9 級以及尚未選擇專精的任何獵人；一旦你選擇專精，就由野獸控制、射擊與生存的內建循環接手。以獵人印記與秘法射擊拉怪，接著對會存活較久的目標使用毒蛇釘刺，三個以上敵人時使用多重射擊，秘法射擊、穩固射擊與自動射擊。會提醒你召喚、復活與治療寵物，並維持雄鷹守護。"
L["rm.retail.hunter.beastmastery.Name"] = "暴雪戰鬥助手"
L["rm.retail.hunter.beastmastery.Description"] = "推薦野獸控制專精使用。醒目提示暴雪戰鬥助手建議的下一個法術，這是在至暗之夜的戰鬥中，遊戲仍允許插件讀取的唯一循環建議（它會自行召喚寵物）；你施法或引導時它會等待。同時提醒戰鬥助手留給你處理的部分：戰鬥中的濺血與你的種族冷卻技能、對可中斷的施法使用駁火反擊，以及戰鬥中只要就緒就使用適者生存。敵人的施法在戰鬥中會被隱藏，因此中斷提醒只會在遊戲顯示它們的場合亮起；正式版中生命力是隱藏的，因此何時使用你的防禦技能（包括心曠神怡與巨龜守護）由你決定。飾品、誤導與寵物照料由你自行處理。"
L["rm.retail.hunter.beastmastery.guide.Name"] = "參考（SimulationCraft 與 Icy Veins）"
L["rm.retail.hunter.beastmastery.guide.Description"] = "僅供參考，預設關閉：最佳化的野獸控制優先順序。在至暗之夜的戰鬥中，充能、冷卻與觸發效果都對插件隱藏，因此它無法在戰鬥中運作；可以閱讀它，或複製後自行實驗。正式版中集中值是隱藏的。拉怪前召喚寵物並以獵人印記標記目標。狂野怒火即將就緒前或鋒銳射擊充能將滿前使用鋒銳射擊；狂野怒火；獸群領袖狂嚎或自然盟友觸發時使用擊殺命令，狂野怒火離就緒還久時也可隨意使用；眼鏡蛇尖牙觸發時使用眼鏡蛇射擊；眼鏡蛇射擊；集中值不足以施放眼鏡蛇射擊時使用鋒銳射擊。黑暗遊俠：凋萎射擊期間使用黑蝕箭，凋萎射擊結束時使用悲鳴箭。三個以上敵人（有獸劈斬時為兩個）：使用狂野痛擊觸發獸劈斬，然後在其持續期間使用擊殺命令、鋒銳射擊與眼鏡蛇射擊。提醒：濺血以及戰鬥助手內建循環中的功能性提醒。"
L["rm.retail.hunter.initial.Name"] = "暴雪戰鬥助手"
L["rm.retail.hunter.initial.Description"] = "在你選擇專精之前推薦使用（此時遊戲回報的是獵人的初始專精）。醒目提示暴雪戰鬥助手建議的下一個法術，這是在至暗之夜的戰鬥中，遊戲仍允許插件讀取的唯一循環建議；你施法或引導時它會等待。同時附上每個獵人內建循環共用的提醒，各項在你學會對應法術後才會出現。當你在 10 級選擇專精後，該專精的內建循環會接手。"
L["rm.retail.hunter.marksmanship.Name"] = "暴雪戰鬥助手"
L["rm.retail.hunter.marksmanship.Description"] = "推薦射擊專精使用。醒目提示暴雪戰鬥助手建議的下一個法術，這是在至暗之夜的戰鬥中，遊戲仍允許插件讀取的唯一循環建議；你施法或引導時它會等待。同時提醒戰鬥助手留給你處理的部分：戰鬥中的強擊與你的種族冷卻技能、對可中斷的施法使用駁火反擊，以及戰鬥中只要就緒就使用適者生存。敵人的施法在戰鬥中會被隱藏，因此中斷提醒只會在遊戲顯示它們的場合亮起；正式版中生命力是隱藏的，因此何時使用你的防禦技能（包括心曠神怡與巨龜守護）由你決定。"
L["rm.retail.hunter.marksmanship.guide.Name"] = "參考（SimulationCraft 與 Icy Veins）"
L["rm.retail.hunter.marksmanship.guide.Description"] = "僅供參考，預設關閉：最佳化的射擊優先順序，會在下一次瞄準射擊前用掉精準射擊。觸發效果與充能在至暗之夜的戰鬥中會被隱藏，因此它無法在戰鬥中運作；正式版中集中值是隱藏的，因此省略了面對成群敵人時 70 集中值的多重射擊。標記目標並以瞄準射擊開場。哨兵：爆裂射擊，箭雨，強擊，在窗口期結束前使用月光戰輪，強擊期間沒有精準射擊時使用瞄準射擊，急速射擊，擊殺射擊，精準射擊觸發時使用多重射擊（有多頭蛇守護時兩個敵人即可）或秘法射擊，瞄準射擊，月光戰輪，穩固射擊。黑暗遊俠：精準射擊觸發時優先使用黑蝕箭，蓄勢待發期間不使用爆裂射擊，瞄準射擊充能溢出前使用瞄準射擊，悲鳴箭。三個以上敵人且有花式射擊時：爆裂射擊，箭雨，使用多重射擊觸發花式射擊，強擊，然後在其持續期間使用急速射擊與瞄準射擊。為了疊滿 30 層百步穿楊或面對未標記的目標而使用強擊的時機由你自行處理。"
L["rm.retail.hunter.survival.Name"] = "暴雪戰鬥助手"
L["rm.retail.hunter.survival.Description"] = "推薦生存專精使用。醒目提示暴雪戰鬥助手建議的下一個法術，這是在至暗之夜的戰鬥中，遊戲仍允許插件讀取的唯一循環建議（它會自行召喚寵物）；你施法或引導時它會等待。同時提醒戰鬥助手留給你處理的部分：戰鬥中的擊倒與你的種族冷卻技能、對可中斷的施法使用封口，以及戰鬥中只要就緒就使用適者生存。敵人的施法在戰鬥中會被隱藏，因此中斷提醒只會在遊戲顯示它們的場合亮起；正式版中生命力是隱藏的，因此何時使用你的防禦技能（包括心曠神怡與巨龜守護）由你決定。"
L["rm.retail.hunter.survival.guide.Name"] = "參考（SimulationCraft）"
L["rm.retail.hunter.survival.guide.Description"] = "僅供參考，預設關閉：SimulationCraft 的生存優先順序：擊殺命令累積長矛之尖，擊倒、火槍、野火炸彈與猛禽一擊消耗它。長矛之尖與充能在至暗之夜的戰鬥中會被隱藏，因此它無法在戰鬥中運作。召喚寵物，以獵人印記標記目標，並以野火炸彈開場。哨兵：沒有長矛之尖時使用擊殺命令，火槍，哨兵印記觸發時使用野火炸彈，擊倒就緒前先使用擊殺命令，擊倒，月光戰輪，猛禽一擊，然後是擊殺命令、野火炸彈與擊倒。獸群領袖：獸群領袖狂嚎觸發時使用擊殺命令，然後在有長矛之尖時使用擊倒、野火炸彈、火槍與猛禽一擊。三個以上敵人時：在擊倒之前使用火槍與野火炸彈，猛禽揮擊。提醒：不在近戰範圍時使用神鷹守護以及功能性提醒。"
L["rm.sod.hunter.melee.Name"] = "近戰（探索賽季）"
L["rm.sod.hunter.melee.Description"] = "在探索賽季伺服器上，紋刻了側翼攻擊、蠍尾獅打擊或橫劈，且未紋刻奇美拉射擊或爆裂射擊時選用。維持側翼攻擊的增益效果，四層猛禽狂怒時使用貓鼬撕咬，機敏打擊時使用蠍尾獅打擊，每次重置時使用猛禽一擊，接著是貓鼬撕咬、蠍尾獅打擊、側翼攻擊與橫劈；獻祭陷阱與摔絆只在空檔時使用。三個以上敵人時使用橫劈與爆炸陷阱；無法接近目標時使用毒蛇釘刺與射擊。提醒：獵鷹守護（60 級前為雄鷹守護）、法力低於 5% 時使用蝮蛇守護、寵物照料（紋刻孤狼後則不需要）、側翼攻擊疊層後使用急速射擊與種族技能、狂野怒火。站位與寵物指令由你自行處理。"
L["rm.sod.hunter.ranged.Name"] = "遠程（探索賽季）"
L["rm.sod.hunter.ranged.Description"] = "探索賽季伺服器上的所有遠程獵人，1 至 60 級；符文紋刻後即納入使用。毒蛇釘刺持續維持，並以奇美拉射擊刷新。有擊殺射擊腿部符文時：四層花式射擊時使用多重射擊，急速射擊期間以及對斬殺範圍內的目標使用擊殺射擊，奇美拉射擊，然後在多重射擊冷卻時使用爆炸陷阱與秘法射擊。沒有它時：奇美拉射擊，兩層狙擊訓練時使用瞄準射擊（沒有該符文時則在自動射擊後立即使用），在奇美拉射擊即將就緒前放置陷阱（冰霜陷阱只用於觸發蓄勢待發），爆裂射擊，穩固射擊，多重射擊，秘法射擊。敵人太近時使用近戰技能，移動時使用瞬發技能，三個以上敵人時使用陷阱、多重射擊與亂射。提醒：雄鷹守護、法力低於 10% 時使用蝮蛇守護、雄獅之心、強擊光環、寵物照料（紋刻孤狼後則不需要）、五層狂亂時使用專注射擊、急速射擊、對精英與在副本中使用種族技能與狂野怒火。紋刻蓄勢待發後，拉怪前要先放置冰霜陷阱。近戰穿插與站位由你自行處理。"
L["rm.tbc.hunter.ranged.simulator.Name"] = "遠程 DPS（模擬器）"
L["rm.tbc.hunter.ranged.simulator.Description"] = "1–70 級，所有專精。以獵人印記、瞄準射擊與自動射擊拉怪，持續自動射擊，目標貼近時使用近戰攻擊。學會穩固射擊之前，維持毒蛇釘刺，只有在法力充足時才把法力用在瞄準射擊、多重射擊與秘法射擊上。62 級起：多重射擊就緒即使用，每次自動射擊後立即使用穩固射擊，以秘法射擊填補空檔，單人時使用毒蛇釘刺。有三個以上敵人與你交戰時，多重射擊就緒即使用。會提醒你守護（法力不足時用蝮蛇守護，法力回到一半時換回雄鷹守護）、寵物照料、擊殺命令、對精英與首領使用主要冷卻技能，以及沉默射擊。寵物指令、誤導、陷阱、亂射、近戰穿插與假死由你自行處理。"
L["rm.tbc.hunter.ranged.wowhead.Name"] = "遠程 DPS（Wowhead）"
L["rm.tbc.hunter.ranged.wowhead.Description"] = "1–70 級，所有專精，遵循 Wowhead 的團隊建議。拉怪、近戰、升級階段的射擊、多目標多重射擊與提醒都與 模擬器 版本相同，但學會穩固射擊後，每次自動射擊後只提供多重射擊與穩固射擊：不以秘法射擊填充（移動時除外）、不用毒蛇釘刺，也沒有蝮蛇守護提醒。寵物指令、誤導、陷阱、亂射、近戰穿插與假死由你自行處理。這是推薦的 模擬器 遠程內建循環的替代選項，預設為停用：啟用它並停用那個，或提高它的優先順序。"
